import {loadCompressed} from './korea-data.mjs';
import {adaptiveOpacity,setLayerVisible,lineSourceOptions} from './adaptive-lines.mjs';
export async function addJapanPortal(map,host){
 const home=[[122.8,24],[146.2,45.7]],[outline,contextEdges]=await Promise.all([loadCompressed('data/japan-context.bin'),loadCompressed('data/japan-context-edges.bin')]);
 map.addSource('japan-portal',{type:'geojson',data:outline,tolerance:.5});
 map.addLayer({id:'japan-portal-fill',type:'fill',source:'japan-portal',paint:{'fill-color':'#d7d7d3','fill-antialias':false}});
 map.addSource('japan-portal-edges',{...lineSourceOptions,data:contextEdges});
 map.addLayer({id:'japan-portal-line',type:'line',source:'japan-portal-edges',layout:{'line-join':'round','line-cap':'round'},paint:{'line-color':'#aaa9a2','line-width':.75,'line-opacity':adaptiveOpacity()}});
 const sidebar=document.createElement('aside');sidebar.id='japan-sidebar';sidebar.className='sidebar';sidebar.hidden=true;sidebar.setAttribute('aria-label','Explore Japan');
 sidebar.innerHTML=`<div class="sidebar-tools"><label class="sr-only" for="j-search">Find a prefecture</label><input id="j-search" type="search" placeholder="Find a prefecture · 都道府県" autocomplete="off"><div id="j-search-results" hidden></div><div class="panel-tabs"><button id="j-tab-explore" hidden aria-pressed="false">Discover</button><button id="j-tab-layers" aria-pressed="true">Map settings</button></div></div>
 <div class="sidebar-scroll"><section id="j-layers-panel"><label class="field-label" for="j-province">Prefecture</label><select id="j-province" data-nav><option value="">All Japan</option></select><section class="layers"><h3>Visible layers</h3><label><span>Prefecture outlines</span><input id="j-province-layer" type="checkbox" checked data-nav></label><label><span>Region names</span><input id="j-label-layer" type="checkbox" checked data-nav></label></section><p>47 prefectures · 都道府県</p></section>
 <section id="j-explore-panel" hidden><div class="selection-top"><button id="j-selection-reset" class="back-button">All Japan</button><div class="japan-flags"><img src="vendor/flag-jp.svg" width="40" height="27" alt="Flag of Japan"><a id="j-flag-source" target="_blank" rel="noopener"><img id="j-prefecture-flag" width="40" height="27" alt=""></a></div></div><span id="j-selection-kind" class="eyebrow"></span><h2 id="j-selection-name"></h2><p id="j-selection-local" class="japanese-name" lang="ja"></p><p id="j-selection-meta" class="selection-meta"></p><section id="j-population" class="population"><h3>Population</h3><p id="j-population-total" class="population-total"></p><p class="population-scope">Entire prefecture</p><p class="population-period">1 October 2025 · Preliminary census</p><a href="https://en.wikipedia.org/wiki/Prefectures_of_Japan" target="_blank" rel="noopener">Population source</a></section><nav class="region-articles"><a id="j-article" target="_blank" rel="noopener">Wikipedia · English</a><a id="j-article-local" target="_blank" rel="noopener">日本語</a></nav></section></div><footer class="sidebar-footer"><a href="data/japan-source.json" target="_blank" rel="noopener">Sources & coverage</a><span>Created by Ethan Hu</span></footer>`;
 document.querySelector('.workspace').insertBefore(sidebar,document.getElementById('map-shell'));
 const $=id=>document.getElementById('j-'+id),index=new Map(),layers=[],urls=[];
 let active=false,ready=false,selected=null,hovered=null,labels=[],loading,preparedPromise,facts;
 const clearLabels=()=>{labels.forEach(m=>m.remove());labels=[];};
 const state=(f,value)=>{if(f)for(const source of ['japan-first','japan-first-selection-edges'])window.AtlasMotion.setFeatureState(map,{source,id:f.properties.id},value);};
 const clearHover=()=>{state(hovered,{hover:false});hovered=null;};
 const panel=name=>{for(const key of ['layers','explore']){$(key+'-panel').hidden=key!==name;$( 'tab-'+key).setAttribute('aria-pressed',String(key===name));}};
 function updateLabels(){if(!active||!ready||host.isMoving?.())return;clearLabels();if(!$('label-layer').checked)return;labels=window.AtlasLabels.render(map,[...index.values()].map(f=>({id:f.properties.id,center:f.properties.center,en:f.properties.en,local:f.properties.ja,selected:f===selected})),'korea-marker');}
 function sync(){if(!ready)return;for(const id of layers)setLayerVisible(map,id,active&&(id!=='japan-first-lines'||$('province-layer').checked));updateLabels();}
 function setMode(){document.getElementById('mode-province').textContent='Prefectures';document.getElementById('mode-province').setAttribute('aria-pressed','true');document.getElementById('mode-prefecture').hidden=true;document.getElementById('mode-lock').hidden=true;document.getElementById('map-hint').textContent='Select a prefecture';}
 async function select(f,fit=true){if(!active||!ready||host.isBusy()||!f)return;state(selected,{selected:false});selected=f;state(f,{selected:true});clearHover();$('search-results').hidden=true;$('search').value='';
  const p=f.properties,r=facts[p.id];$('province').value=p.id;$('selection-name').textContent=p.en;$('selection-local').textContent=p.ja;$('selection-kind').textContent=p.type.toUpperCase();$('selection-meta').textContent='Capital: '+p.capital+' · '+p.capitalLocal;
  $('prefecture-flag').src=r.flag.file;$('prefecture-flag').alt='Flag of '+p.en;$('flag-source').href=r.flag.page;$('flag-source').title=p.en+' prefectural flag — source and license';$('population-total').textContent=r.population.toLocaleString('en-US');
  $('article').href=r.article;$('article-local').href='https://ja.wikipedia.org/wiki/'+encodeURIComponent(p.ja);
  window.AtlasStatistics.renderStatistics($('selection-meta'),'japan:'+p.id);$('tab-explore').hidden=false;panel('explore');sidebar.querySelector('.sidebar-scroll').scrollTop=0;
  const breadcrumb=document.getElementById('breadcrumb-region');breadcrumb.hidden=false;breadcrumb.textContent=p.en+' · '+p.ja;sync();if(fit)await host.fit(p.focusBounds||p.bounds,11);
 }
 async function reset(fit=true){if(!ready||host.isBusy())return;state(selected,{selected:false});selected=null;$('province').value='';$('tab-explore').hidden=true;panel('layers');document.getElementById('breadcrumb-region').hidden=true;sync();if(fit)await host.fit(home,8);}
 function preload(){if(!preparedPromise)preparedPromise=new Promise((resolve,reject)=>{const worker=new Worker(new URL('./japan-worker.mjs',import.meta.url),{type:'module'});worker.onmessage=e=>{worker.terminate();e.data.error?reject(Error(e.data.error)):resolve(e.data.result);};worker.onerror=e=>{worker.terminate();reject(Error(e.message));};}).catch(e=>{preparedPromise=null;throw e;});return preparedPromise;}
 async function warm(){if(ready)return;if(loading)return loading;loading=(async()=>{
  const [prepared,details]=await Promise.all([preload(),fetch('data/japan-facts.json').then(r=>{if(!r.ok)throw Error('Japan facts unavailable');return r.json();})]);facts=details;
  for(const [id,blob] of Object.entries(prepared.sources)){const url=URL.createObjectURL(blob);urls.push(url);map.addSource(id,{type:'geojson',data:url,promoteId:'id',tolerance:.375,maxzoom:18,buffer:128,attribution:'Japan: <a href="https://github.com/piuccio/open-data-jp-prefectures-geojson">MLIT / piuccio</a>'});}
  for(const f of prepared.metadata)index.set(f.properties.id,f);
  const definitions=[{id:'japan-first-fill',type:'fill',source:'japan-first',paint:{'fill-color':['case',['boolean',['feature-state','selected'],false],'#efd2d8',['boolean',['feature-state','hover'],false],'#f6e6e9','#fffdfd'],'fill-opacity':1,'fill-antialias':false}},{id:'japan-first-lines',type:'line',source:'japan-first-edges',paint:{'line-color':'#bd7480','line-width':.8,'line-opacity':adaptiveOpacity()}},{id:'japan-first-selected',type:'line',source:'japan-first-selection-edges',paint:{'line-color':'#bc002d','line-width':1.8,'line-opacity':adaptiveOpacity(['case',['boolean',['feature-state','selected'],false],1,0])}}];
  for(const layer of definitions){map.addLayer(layer);layers.push(layer.id);setLayerVisible(map,layer.id,false);}
  for(const f of [...index.values()].sort((a,b)=>a.properties.en.localeCompare(b.properties.en)))$('province').append(new Option(f.properties.en+' · '+f.properties.ja,f.properties.id));ready=true;
 })().catch(e=>{loading=null;for(const id of layers.splice(0))if(map.getLayer(id))map.removeLayer(id);for(const id of ['japan-first','japan-first-edges','japan-first-selection-edges'])if(map.getSource(id))map.removeSource(id);urls.splice(0).forEach(URL.revokeObjectURL);index.clear();throw e;});return loading;}
 const picked=point=>{const hit=window.AtlasMotion.queryRegions(map,point,{layers:['japan-first-fill']})[0];return hit&&index.get(hit.properties.id);};
 map.on('click',e=>{if(active&&ready&&!host.isBusy())select(picked(e.point));});map.on('mousemove',e=>{if(!active||!ready||host.isBusy()||map.isMoving())return;const f=picked(e.point);if(f!==hovered){clearHover();hovered=f;state(f,{hover:true});}map.getCanvas().style.cursor=f?'pointer':'';});map.on('movestart',clearHover);map.on('moveend',updateLabels);map.on('resize',updateLabels);
 $('province').onchange=()=>{$('province').value?select(index.get($('province').value)):reset();};$('selection-reset').onclick=()=>reset();$('tab-explore').onclick=()=>panel('explore');$('tab-layers').onclick=()=>panel('layers');for(const id of ['province-layer','label-layer'])$(id).onchange=sync;
 const norm=s=>s.normalize('NFD').replace(/\p{M}/gu,'').toLowerCase();$('search').oninput=()=>{const q=norm($('search').value),box=$('search-results');box.replaceChildren();box.hidden=!q;if(!q)return;for(const f of [...index.values()].filter(f=>norm(f.properties.en+' '+f.properties.ja).includes(q))){const b=document.createElement('button');b.className='search-result';b.textContent=f.properties.en+' · '+f.properties.ja;b.onclick=()=>select(f);box.append(b);}};
 return{preload,warm,sync,setMode,updateLabels,pauseLabels:clearLabels,context(value){map.setPaintProperty('japan-portal-line','line-opacity',value?0:adaptiveOpacity());},get ready(){return ready;},get active(){return active;},getSelection:()=>selected?.properties.id||null,restore:async id=>{if(index.has(id))await select(index.get(id),false);},async enter(fit=true){await warm();active=true;sidebar.hidden=false;setMode();await reset(fit);sync();},leave(){active=false;sidebar.hidden=true;clearLabels();clearHover();sync();document.getElementById('mode-prefecture').hidden=false;document.getElementById('mode-lock').hidden=false;},home:()=>reset(),viewParent:()=>reset(),random(){const list=[...index.values()];select(list[Math.floor(Math.random()*list.length)]);}};
}
